-- 048 — Versions anglaises des textes des admins (lues dans toutes les langues sauf le français) :
-- guides pays, page « Le LFK », frise des proviseurs, descriptions des partenaires. Le texte
-- français ne change pas. Chaque mise à jour ne s’applique que si le texte n’a pas été modifié
-- depuis l’export du 7 octobre 2026 (sinon elle ne fait rien). Nécessite la migration 047.

-- Guides pays : France (déjà enregistré) + Espagne, Canada, États-Unis, Royaume-Uni, Italie (jusqu’ici
-- fournis par le code), chacun avec sa version anglaise. Accepte aussi la première version de la 048.
update public.app_settings set value = $en$[{"id":"guide-fr","country":"FR","title":"Arriver en France","published":true,"steps":[{"id":"g-nationalite","phase":"before","title":"Vérifier si vous avez besoin d’un visa","body":"Nationalité française ou européenne : pas de visa ni de titre de séjour, passez directement au logement et à la sécurité sociale.\nAutres nationalités : un visa long séjour « étudiant » est nécessaire. Commencez les démarches dès l’admission, les délais peuvent dépasser un mois.","titleEn":"Check whether you need a visa","bodyEn":"French or European nationality: no visa or residence permit needed, go straight to housing and social security.\nOther nationalities: a long-stay « student » visa is required. Start as soon as you are admitted: it can take more than a month."},{"id":"g-campus","phase":"before","title":"Campus France / Études en France","body":"Dans de nombreux pays, la candidature et le visa passent d’abord par la procédure « Études en France » de Campus France (dossier en ligne, entretien). Vérifiez sur le site si elle s’applique à votre pays.","url":"https://www.campusfrance.org","urlLabel":"Campus France","titleEn":"Campus France / Études en France","bodyEn":"In many countries, the application and the visa first go through Campus France’s « Études en France » procedure (online file, interview). Check on the website whether it applies to your country.","urlLabelEn":"Campus France"},{"id":"g-visa","phase":"before","title":"Demander le visa long séjour (VLS-TS)","body":"Créez votre demande sur France-Visas, puis prenez rendez-vous au centre de visas pour déposer le dossier et vos empreintes.\nPièces habituelles : passeport valide, lettre d’admission, justificatif de ressources (environ 615 € par mois), justificatif de logement, photos d’identité.","url":"https://france-visas.gouv.fr","urlLabel":"France-Visas","titleEn":"Apply for the long-stay visa (VLS-TS)","bodyEn":"Create your application on France-Visas, then book an appointment at the visa centre to hand in your file and fingerprints.\nUsual documents: valid passport, admission letter, proof of funds (about €615 a month), proof of accommodation, ID photos.","urlLabelEn":"France-Visas"},{"id":"g-docs","phase":"before","title":"Préparer ses documents","body":"Emportez les originaux et des copies : passeport, acte de naissance (avec traduction si besoin), diplômes et relevés de notes, attestation du bac, photos d’identité. Gardez aussi une version scannée dans votre téléphone.","titleEn":"Prepare your documents","bodyEn":"Bring the originals and copies: passport, birth certificate (translated if needed), diplomas and transcripts, baccalauréat certificate, ID photos. Keep a scanned copy on your phone too."},{"id":"g-logement","phase":"before","title":"Trouver un logement","body":"Résidences du CROUS (dossier social étudiant), résidences privées, colocations. Pour la caution, la garantie Visale est gratuite pour les étudiants.\nDemandez aussi aux alumni de votre ville dans Repère : ils connaissent les bons plans.","url":"https://www.messervices.etudiant.gouv.fr","urlLabel":"Mes services étudiant (CROUS)","titleEn":"Find accommodation","bodyEn":"CROUS residences (student social file), private residences, flatshares. For the deposit, the Visale guarantee is free for students.\nAlso ask the alumni in your city on Repère: they know the good deals.","urlLabelEn":"Mes services étudiant (CROUS)"},{"id":"g-cvec","phase":"before","title":"Payer la CVEC","body":"La Contribution vie étudiante et de campus (environ 105 €) est obligatoire avant l’inscription administrative dans la plupart des établissements. Gardez l’attestation.","url":"https://cvec.etudiant.gouv.fr","urlLabel":"CVEC","titleEn":"Pay the CVEC","bodyEn":"The student and campus life contribution (about €105) is compulsory before administrative enrolment in most institutions. Keep the certificate.","urlLabelEn":"CVEC"},{"id":"g-validation","phase":"arrival","title":"Valider son visa (VLS-TS)","body":"Dans les 3 mois après l’arrivée, validez votre visa en ligne sur le site de l’ANEF et payez la taxe (timbre fiscal). Sans cette validation, vous êtes en situation irrégulière à la fin des 3 mois.","url":"https://administration-etrangers-en-france.interieur.gouv.fr","urlLabel":"ANEF","titleEn":"Validate your visa (VLS-TS)","bodyEn":"Within 3 months of arriving, validate your visa online on the ANEF website and pay the fee (tax stamp). Without this validation, you are staying illegally once the 3 months are over.","urlLabelEn":"ANEF"},{"id":"g-secu","phase":"arrival","title":"S’inscrire à la sécurité sociale","body":"Inscription gratuite : étudiants étrangers sur le site dédié de l’Assurance maladie, étudiants français sur ameli.fr. Vous obtenez un numéro de sécurité sociale puis la carte Vitale (envoyez la photo et la pièce d’identité demandées).","url":"https://etudiant-etranger.ameli.fr","urlLabel":"Assurance maladie — étudiants étrangers","titleEn":"Register for social security","bodyEn":"Free registration: international students on the Assurance maladie’s dedicated website, French students on ameli.fr. You get a social security number, then the Carte Vitale (send the photo and ID requested).","urlLabelEn":"Assurance maladie — international students"},{"id":"g-banque","phase":"arrival","title":"Ouvrir un compte bancaire","body":"Il faut un RIB français pour le loyer, la CAF et un job. Apportez passeport, justificatif de domicile et attestation d’inscription. Les banques en ligne sont souvent plus rapides.","titleEn":"Open a bank account","bodyEn":"You need a French bank account (RIB) for rent, the CAF and a job. Bring your passport, proof of address and enrolment certificate. Online banks are often faster."},{"id":"g-tel","phase":"arrival","title":"Carte SIM et numéro français","body":"Un forfait sans engagement suffit. Le numéro français sert pour la banque, la CAF et les démarches.","titleEn":"SIM card and French number","bodyEn":"A no-commitment plan is enough. A French number is needed for the bank, the CAF and paperwork."},{"id":"g-assurance","phase":"arrival","title":"Assurance habitation","body":"Obligatoire pour louer un logement : demandez l’attestation à remettre au propriétaire ou à la résidence.","titleEn":"Home insurance","bodyEn":"Compulsory to rent: ask for the certificate to give to the landlord or the residence."},{"id":"g-caf","phase":"months","title":"Demander l’aide au logement (CAF)","body":"Les étudiants, y compris étrangers, peuvent avoir droit à l’APL. Faites la demande en ligne dès votre entrée dans le logement : l’aide n’est pas rétroactive.","url":"https://www.caf.fr","urlLabel":"CAF","titleEn":"Apply for housing benefit (CAF)","bodyEn":"Students, including international students, may be entitled to the APL. Apply online as soon as you move in: the benefit is not backdated.","urlLabelEn":"CAF"},{"id":"g-mutuelle","phase":"months","title":"Mutuelle et médecin traitant","body":"La sécurité sociale rembourse une partie des soins ; une complémentaire santé (mutuelle) couvre le reste. Déclarez un médecin traitant pour être mieux remboursé.","titleEn":"Top-up insurance and GP","bodyEn":"Social security covers part of the costs; a top-up health insurance (mutuelle) covers the rest. Register a regular doctor (médecin traitant) to be better reimbursed."},{"id":"g-transport","phase":"months","title":"Transports","body":"Les villes proposent des abonnements étudiants à prix réduit (par exemple Imagine R en Île-de-France).","titleEn":"Transport","bodyEn":"Cities offer discounted student passes (for example Imagine R in the Paris region)."},{"id":"g-renouvellement","phase":"year","title":"Renouveler son titre de séjour","body":"Faites la demande en ligne sur l’ANEF au moins 2 mois avant la fin de validité de votre visa ou titre de séjour.","url":"https://administration-etrangers-en-france.interieur.gouv.fr","urlLabel":"ANEF","titleEn":"Renew your residence permit","bodyEn":"Apply online on the ANEF at least 2 months before your visa or residence permit expires.","urlLabelEn":"ANEF"},{"id":"g-job","phase":"year","title":"Job étudiant","body":"Avec un titre de séjour étudiant, vous pouvez travailler jusqu’à 964 heures par an. Pensez aux jobs proposés par votre établissement et le CROUS.","titleEn":"Student job","bodyEn":"With a student residence permit, you can work up to 964 hours a year. Look at the jobs offered by your institution and the CROUS."},{"id":"g-impots","phase":"year","title":"Déclarer ses revenus","body":"Au printemps, la déclaration de revenus est souvent nécessaire (même sans revenus) pour garder vos droits, notamment à la CAF.","url":"https://www.impots.gouv.fr","urlLabel":"impots.gouv.fr","titleEn":"File your tax return","bodyEn":"In spring, a tax return is often needed (even with no income) to keep your rights, especially with the CAF.","urlLabelEn":"impots.gouv.fr"}],"titleEn":"Arriving in France"},{"id":"guide-es","country":"ES","title":"Partir étudier en Espagne","intro":"Les étapes pour s’installer en Espagne : visa (hors Union européenne), NIE, empadronamiento, santé et vie sur place.","published":true,"steps":[{"id":"es-visa","phase":"before","title":"Visa d’études (hors Union européenne)","body":"Nationalité française ou européenne : pas de visa.\nAutres nationalités : demandez un visa d’études (« visado de estudios ») au consulat d’Espagne dont vous dépendez, dès la lettre d’admission. Pièces habituelles : passeport, admission, justificatif de ressources, assurance santé privée sans franchise, certificat médical et extrait de casier judiciaire (légalisés ou apostillés, avec traduction officielle).","url":"https://www.exteriores.gob.es","urlLabel":"Ministère des Affaires étrangères (consulats)","titleEn":"Student visa (outside the European Union)","bodyEn":"French or European nationality: no visa.\nOther nationalities: apply for a student visa (« visado de estudios ») at the Spanish consulate for your area as soon as you receive your admission letter. Usual documents: passport, admission, proof of funds, private health insurance with no excess, medical certificate and criminal record certificate (legalised or apostilled, with an official translation).","urlLabelEn":"Ministry of Foreign Affairs (consulates)"},{"id":"es-docs","phase":"before","title":"Préparer ses documents","body":"Passeport, acte de naissance, diplômes et relevés de notes, attestation du bac. Pour certaines démarches, les documents étrangers doivent être apostillés et accompagnés d’une traduction assermentée (« traducción jurada »). Gardez une copie scannée de tout.","titleEn":"Prepare your documents","bodyEn":"Passport, birth certificate, diplomas and transcripts, baccalauréat certificate. For some procedures, foreign documents must be apostilled and come with a sworn translation (« traducción jurada »). Keep a scanned copy of everything."},{"id":"es-sante","phase":"before","title":"Assurance santé","body":"Étudiants européens : demandez la Carte européenne d’assurance maladie (CEAM) avant le départ.\nAutres nationalités : une assurance santé privée couvrant tout le séjour est exigée pour le visa.","titleEn":"Health insurance","bodyEn":"European students: get the European Health Insurance Card (EHIC) before leaving.\nOther nationalities: private health insurance covering the whole stay is required for the visa."},{"id":"es-logement","phase":"before","title":"Trouver un logement","body":"Résidences universitaires (« residencias » et « colegios mayores »), colocations (« pisos compartidos »). Les annonces se trouvent sur les grands sites immobiliers. Demandez aux alumni installés en Espagne dans Repère.","titleEn":"Find accommodation","bodyEn":"University residences (« residencias » and « colegios mayores »), flatshares (« pisos compartidos »). Listings are on the main property websites. Ask the alumni living in Spain on Repère."},{"id":"es-padron","phase":"arrival","title":"S’inscrire à la mairie (empadronamiento)","body":"Inscrivez-vous au registre de la mairie de votre ville avec votre contrat de location et votre passeport. Le certificat d’empadronamiento est demandé pour beaucoup d’autres démarches.","titleEn":"Register at the town hall (empadronamiento)","bodyEn":"Register on your town hall’s register with your rental contract and passport. The empadronamiento certificate is asked for in many other procedures."},{"id":"es-nie","phase":"arrival","title":"NIE et titre de séjour","body":"Étudiants européens restant plus de 3 mois : demandez le certificat d’enregistrement de citoyen de l’UE (avec votre NIE) auprès de la police ou de l’office des étrangers, sur rendez-vous.\nAutres nationalités : demandez la carte de séjour (TIE) dans le mois qui suit l’arrivée, sur rendez-vous (« cita previa »).","url":"https://sede.administracionespublicas.gob.es","urlLabel":"Cita previa extranjería","titleEn":"NIE and residence card","bodyEn":"European students staying more than 3 months: apply for the EU citizen registration certificate (with your NIE) at the police or the foreigners’ office, by appointment.\nOther nationalities: apply for the residence card (TIE) within a month of arriving, by appointment (« cita previa »).","urlLabelEn":"Cita previa extranjería"},{"id":"es-banque","phase":"arrival","title":"Compte bancaire et carte SIM","body":"Un compte espagnol facilite le loyer et les abonnements ; le NIE est souvent demandé. Une carte SIM prépayée suffit au début.","titleEn":"Bank account and SIM card","bodyEn":"A Spanish account makes rent and subscriptions easier; the NIE is often required. A prepaid SIM card is enough at first."},{"id":"es-transport","phase":"months","title":"Transports","body":"Les grandes villes et régions proposent des abonnements jeunes à prix réduit (« abono joven »). Renseignez-vous auprès du réseau de votre ville.","titleEn":"Transport","bodyEn":"Large cities and regions offer discounted youth passes (« abono joven »). Ask your city’s transport network."},{"id":"es-travail","phase":"year","title":"Travailler pendant les études","body":"Les étudiants européens peuvent travailler librement. Avec un titre de séjour étudiant, le travail est autorisé à temps partiel, dans la limite fixée par la loi, compatible avec les études.","titleEn":"Working while studying","bodyEn":"European students can work freely. With a student residence permit, part-time work compatible with your studies is allowed, within the limit set by law."},{"id":"es-renouvellement","phase":"year","title":"Renouveler son titre de séjour","body":"Hors Union européenne : demandez le renouvellement de votre autorisation de séjour pour études avant son expiration (en général dans les 60 jours qui précèdent).","titleEn":"Renew your residence permit","bodyEn":"Outside the European Union: apply to renew your student residence authorisation before it expires (usually in the 60 days before)."}],"titleEn":"Studying in Spain","introEn":"The steps to settle in Spain: visa (outside the European Union), NIE, empadronamiento, health and daily life."},{"id":"guide-ca","country":"CA","title":"Partir étudier au Canada","intro":"Permis d’études, CAQ pour le Québec, arrivée, numéro d’assurance sociale et vie étudiante au Canada.","published":true,"steps":[{"id":"ca-caq","phase":"before","title":"Québec : le CAQ d’abord","body":"Pour étudier au Québec, demandez d’abord le Certificat d’acceptation du Québec (CAQ) au ministère de l’Immigration du Québec, avec votre lettre d’admission. Il est nécessaire avant le permis d’études fédéral.\nLes étudiants français bénéficient de frais de scolarité préférentiels au Québec : vérifiez auprès de votre université.","url":"https://www.quebec.ca/education/etudier-quebec","urlLabel":"Étudier au Québec","titleEn":"Quebec: the CAQ first","bodyEn":"To study in Quebec, first apply for the Quebec Acceptance Certificate (CAQ) from Quebec’s Ministry of Immigration, with your admission letter. You need it before the federal study permit.\nFrench students pay preferential tuition fees in Quebec: check with your university.","urlLabelEn":"Studying in Quebec"},{"id":"ca-permis","phase":"before","title":"Demander le permis d’études","body":"Demande en ligne auprès d’Immigration Canada (IRCC) : lettre d’acceptation d’un établissement désigné, attestation de la province ou du territoire (ou le CAQ pour le Québec), preuve de ressources, passeport, puis données biométriques. Les délais peuvent être longs : commencez dès l’admission.","url":"https://www.canada.ca/fr/immigration-refugies-citoyennete/services/etudier-canada.html","urlLabel":"Étudier au Canada (IRCC)","titleEn":"Apply for the study permit","bodyEn":"Apply online to Immigration Canada (IRCC): acceptance letter from a designated institution, attestation from the province or territory (or the CAQ for Quebec), proof of funds, passport, then biometrics. It can take a long time: start as soon as you are admitted.","urlLabelEn":"Study in Canada (IRCC)"},{"id":"ca-sante","phase":"before","title":"Assurance maladie","body":"La couverture dépend de la province : certaines incluent les étudiants étrangers, d’autres exigent l’assurance de l’université. Au Québec, les étudiants français peuvent être couverts par la RAMQ grâce à l’entente France-Québec (formulaire à obtenir avant le départ auprès de l’Assurance maladie).","titleEn":"Health insurance","bodyEn":"Coverage depends on the province: some include international students, others require the university’s insurance. In Quebec, French students can be covered by the RAMQ thanks to the France–Quebec agreement (form to get from the Assurance maladie before leaving)."},{"id":"ca-logement","phase":"before","title":"Trouver un logement","body":"Résidences universitaires (à réserver tôt), colocations, appartements. Méfiez-vous des annonces qui demandent un paiement avant toute visite. Les alumni installés au Canada peuvent vous conseiller (Repère).","titleEn":"Find accommodation","bodyEn":"University residences (book early), flatshares, apartments. Beware of listings that ask for payment before any visit. Alumni living in Canada can advise you (Repère)."},{"id":"ca-arrivee","phase":"arrival","title":"Au point d’entrée","body":"À l’aéroport, l’agent des services frontaliers vous remet le permis d’études. Ayez sur vous la lettre d’introduction, la lettre d’admission, la preuve de ressources (et le CAQ pour le Québec). Vérifiez les informations du permis avant de quitter le guichet.","titleEn":"At the port of entry","bodyEn":"At the airport, the border services officer gives you your study permit. Carry the letter of introduction, the admission letter, proof of funds (and the CAQ for Quebec). Check the details on the permit before leaving the counter."},{"id":"ca-nas","phase":"arrival","title":"Numéro d’assurance sociale (NAS)","body":"Indispensable pour travailler et être payé. Demandez-le gratuitement auprès de Service Canada, en ligne ou sur place, avec votre permis d’études.","url":"https://www.canada.ca/fr/emploi-developpement-social/services/numero-assurance-sociale.html","urlLabel":"Service Canada — NAS","titleEn":"Social Insurance Number (SIN)","bodyEn":"Essential to work and get paid. Apply for free at Service Canada, online or in person, with your study permit.","urlLabelEn":"Service Canada — SIN"},{"id":"ca-banque","phase":"arrival","title":"Compte bancaire et téléphone","body":"Les grandes banques proposent des comptes pour étudiants étrangers, souvent ouvrables dès l’arrivée avec passeport et permis d’études. Prenez un forfait mobile local.","titleEn":"Bank account and phone","bodyEn":"The big banks offer accounts for international students, often opened on arrival with your passport and study permit. Get a local mobile plan."},{"id":"ca-travail","phase":"year","title":"Travailler pendant les études","body":"Le permis d’études permet en général de travailler sur le campus, et hors campus dans une limite d’heures par semaine pendant les sessions (sans limite pendant les congés). Vérifiez les conditions inscrites sur votre permis.","titleEn":"Working while studying","bodyEn":"The study permit generally allows you to work on campus, and off campus within a weekly limit of hours during terms (no limit during breaks). Check the conditions written on your permit."},{"id":"ca-impots","phase":"year","title":"Déclarer ses revenus","body":"Chaque printemps, faites votre déclaration de revenus (fédérale, et provinciale au Québec), même avec peu de revenus : elle ouvre droit à certains crédits et remboursements.","titleEn":"File your tax return","bodyEn":"Every spring, file your tax return (federal, and provincial in Quebec), even with little income: it gives access to some credits and refunds."},{"id":"ca-renouvellement","phase":"year","title":"Prolonger son permis","body":"Demandez la prolongation du permis d’études (et du CAQ au Québec) avant sa date d’expiration si vos études continuent.","titleEn":"Extend your permit","bodyEn":"Apply to extend your study permit (and your CAQ in Quebec) before it expires if your studies continue."}],"titleEn":"Studying in Canada","introEn":"Study permit, CAQ for Quebec, arrival, Social Insurance Number and student life in Canada."},{"id":"guide-us","country":"US","title":"Partir étudier aux États-Unis","intro":"Formulaire I-20, visa F-1, arrivée sur le campus et règles à respecter pendant les études aux États-Unis.","published":true,"steps":[{"id":"us-i20","phase":"before","title":"Recevoir le formulaire I-20","body":"Après l’admission, l’université vous envoie le formulaire I-20 (après preuve de vos ressources). C’est la base de toute la procédure : vérifiez nom, dates et programme.","url":"https://studyinthestates.dhs.gov","urlLabel":"Study in the States","titleEn":"Receive Form I-20","bodyEn":"After admission, the university sends you Form I-20 (once you have shown proof of funds). The whole procedure rests on it: check your name, dates and programme.","urlLabelEn":"Study in the States"},{"id":"us-sevis","phase":"before","title":"Payer les frais SEVIS (I-901)","body":"Payez les frais SEVIS en ligne avec le numéro de votre I-20, avant l’entretien de visa. Gardez le reçu.","url":"https://www.fmjfee.com","urlLabel":"Frais SEVIS I-901","titleEn":"Pay the SEVIS fee (I-901)","bodyEn":"Pay the SEVIS fee online with your I-20 number, before the visa interview. Keep the receipt.","urlLabelEn":"SEVIS I-901 fee"},{"id":"us-visa","phase":"before","title":"Visa étudiant F-1","body":"Remplissez le formulaire DS-160, payez les frais et prenez rendez-vous à l’ambassade ou au consulat des États-Unis pour l’entretien. L’ESTA ne permet pas d’étudier : le visa F-1 est obligatoire.","url":"https://travel.state.gov/content/travel/en/us-visas/study.html","urlLabel":"Visas étudiants (Département d’État)","titleEn":"F-1 student visa","bodyEn":"Fill in Form DS-160, pay the fee and book an interview at the US embassy or consulate. The ESTA does not allow you to study: the F-1 visa is compulsory.","urlLabelEn":"Student visas (Department of State)"},{"id":"us-sante","phase":"before","title":"Assurance santé","body":"Les soins sont très chers : la plupart des universités imposent leur assurance santé, ou une assurance équivalente. Vérifiez ce qui est exigé avant le départ.","titleEn":"Health insurance","bodyEn":"Healthcare is very expensive: most universities require their own health insurance, or an equivalent one. Check what is required before leaving."},{"id":"us-arrivee","phase":"arrival","title":"Entrée et arrivée sur le campus","body":"Vous pouvez entrer au plus tôt 30 jours avant le début du programme indiqué sur l’I-20. Présentez-vous ensuite au bureau international de l’université (le « DSO ») pour valider votre arrivée dans SEVIS.","titleEn":"Entering the country and arriving on campus","bodyEn":"You can enter at the earliest 30 days before the programme start date on your I-20. Then report to the university’s international office (the « DSO ») to confirm your arrival in SEVIS."},{"id":"us-banque","phase":"arrival","title":"Compte bancaire et téléphone","body":"Ouvrez un compte local (passeport, I-20, adresse) et prenez un forfait mobile. Le numéro de sécurité sociale (SSN) n’est délivré que si vous avez un emploi autorisé.","titleEn":"Bank account and phone","bodyEn":"Open a local account (passport, I-20, address) and get a mobile plan. A Social Security Number (SSN) is only issued if you have authorised employment."},{"id":"us-statut","phase":"months","title":"Garder son statut F-1","body":"Restez inscrit à temps plein, prévenez le bureau international en cas de changement d’adresse ou de programme, et faites signer votre I-20 avant chaque voyage hors des États-Unis.","titleEn":"Keep your F-1 status","bodyEn":"Stay enrolled full time, tell the international office if your address or programme changes, and have your I-20 signed before every trip outside the United States."},{"id":"us-travail","phase":"year","title":"Travailler pendant les études","body":"Le visa F-1 autorise un emploi sur le campus, à temps partiel pendant les cours. Le travail hors campus passe par les dispositifs CPT ou OPT, avec l’accord du bureau international.","titleEn":"Working while studying","bodyEn":"The F-1 visa allows on-campus work, part time during classes. Off-campus work goes through CPT or OPT, with the international office’s approval."},{"id":"us-impots","phase":"year","title":"Formulaire fiscal annuel","body":"Chaque année, les étudiants F-1 doivent envoyer le formulaire 8843, même sans revenus, et une déclaration de revenus s’ils ont travaillé. Le bureau international propose souvent de l’aide.","url":"https://www.irs.gov","urlLabel":"IRS","titleEn":"Annual tax form","bodyEn":"Every year, F-1 students must send Form 8843, even with no income, and a tax return if they worked. The international office often offers help.","urlLabelEn":"IRS"}],"titleEn":"Studying in the United States","introEn":"Form I-20, F-1 visa, arriving on campus and the rules to follow while studying in the United States."},{"id":"guide-gb","country":"GB","title":"Partir étudier au Royaume-Uni","intro":"Student visa, CAS, surcharge santé, inscription chez un médecin et vie étudiante au Royaume-Uni.","published":true,"steps":[{"id":"gb-cas","phase":"before","title":"Recevoir le CAS","body":"Une fois votre offre acceptée (souvent via UCAS pour une licence), l’université vous délivre un CAS (Confirmation of Acceptance for Studies), indispensable pour la demande de visa.","url":"https://www.ucas.com","urlLabel":"UCAS","titleEn":"Receive your CAS","bodyEn":"Once you accept your offer (often through UCAS for a bachelor’s degree), the university issues a CAS (Confirmation of Acceptance for Studies), which you need for the visa application.","urlLabelEn":"UCAS"},{"id":"gb-visa","phase":"before","title":"Demander le Student visa","body":"Depuis le Brexit, les étudiants français et européens ont aussi besoin d’un Student visa (sauf statut EU Settlement Scheme). Demande en ligne jusqu’à 6 mois avant le début des cours : CAS, passeport, preuve de ressources et de niveau d’anglais selon les cas. Le visa est délivré sous forme électronique (eVisa) dans votre compte UKVI.","url":"https://www.gov.uk/student-visa","urlLabel":"GOV.UK — Student visa","titleEn":"Apply for the Student visa","bodyEn":"Since Brexit, French and European students also need a Student visa (unless they have EU Settlement Scheme status). Apply online up to 6 months before your course starts: CAS, passport, proof of funds and, in some cases, of your English level. The visa is issued electronically (eVisa) in your UKVI account.","urlLabelEn":"GOV.UK — Student visa"},{"id":"gb-ihs","phase":"before","title":"Surcharge santé (IHS)","body":"Lors de la demande de visa, vous payez l’Immigration Health Surcharge, qui donne accès au système de santé public (NHS) pendant vos études.","url":"https://www.gov.uk/healthcare-immigration-application","urlLabel":"GOV.UK — IHS","titleEn":"Health surcharge (IHS)","bodyEn":"When you apply for the visa, you pay the Immigration Health Surcharge, which gives access to the public health service (NHS) during your studies.","urlLabelEn":"GOV.UK — IHS"},{"id":"gb-logement","phase":"before","title":"Trouver un logement","body":"Les résidences universitaires (« halls ») sont souvent garanties en première année si vous postulez avant la date limite. Ensuite : colocations (« flatshares »).","titleEn":"Find accommodation","bodyEn":"University residences (« halls ») are often guaranteed in first year if you apply before the deadline. After that: flatshares."},{"id":"gb-gp","phase":"arrival","title":"S’inscrire chez un médecin (GP)","body":"Inscrivez-vous dès l’arrivée auprès d’un cabinet de médecins généralistes (GP) proche de chez vous : c’est gratuit et nécessaire pour accéder aux soins du NHS.","url":"https://www.nhs.uk/nhs-services/gps/how-to-register-with-a-gp-surgery/","urlLabel":"NHS — s’inscrire chez un GP","titleEn":"Register with a doctor (GP)","bodyEn":"As soon as you arrive, register with a GP surgery near you: it is free and needed to access NHS care.","urlLabelEn":"NHS — register with a GP"},{"id":"gb-banque","phase":"arrival","title":"Compte bancaire et téléphone","body":"Ouvrez un compte (attestation d’inscription de l’université) et prenez une carte SIM. Les banques en ligne sont souvent plus rapides.","titleEn":"Bank account and phone","bodyEn":"Open an account (enrolment letter from the university) and get a SIM card. Online banks are often faster."},{"id":"gb-ni","phase":"arrival","title":"National Insurance number","body":"Nécessaire si vous travaillez. La demande se fait en ligne.","url":"https://www.gov.uk/apply-national-insurance-number","urlLabel":"GOV.UK — National Insurance","titleEn":"National Insurance number","bodyEn":"Needed if you work. You apply online.","urlLabelEn":"GOV.UK — National Insurance"},{"id":"gb-council","phase":"months","title":"Council tax et transports","body":"Les étudiants à temps plein sont exonérés de la council tax : demandez l’attestation à l’université. Pensez à la carte de réduction 16-25 Railcard et aux tarifs étudiants des transports locaux.","titleEn":"Council tax and transport","bodyEn":"Full-time students are exempt from council tax: ask the university for the certificate. Think of the 16-25 Railcard and student fares on local transport."},{"id":"gb-travail","phase":"year","title":"Travailler pendant les études","body":"Le Student visa autorise en général un nombre limité d’heures de travail par semaine pendant les cours (plein temps pendant les vacances). Le nombre exact figure sur votre visa.","titleEn":"Working while studying","bodyEn":"The Student visa generally allows a limited number of working hours per week during term (full time during holidays). The exact number is on your visa."},{"id":"gb-graduate","phase":"year","title":"Après le diplôme","body":"Le Graduate visa permet de rester travailler après le diplôme pendant une durée limitée. Les règles évoluent : vérifiez-les sur GOV.UK avant la fin de vos études.","url":"https://www.gov.uk/graduate-visa","urlLabel":"GOV.UK — Graduate visa","titleEn":"After graduating","bodyEn":"The Graduate visa lets you stay and work after your degree for a limited time. The rules change: check them on GOV.UK before your studies end.","urlLabelEn":"GOV.UK — Graduate visa"}],"titleEn":"Studying in the United Kingdom","introEn":"Student visa, CAS, health surcharge, registering with a doctor and student life in the United Kingdom."},{"id":"guide-it","country":"IT","title":"Partir étudier en Italie","intro":"Pré-inscription Universitaly, visa (hors Union européenne), codice fiscale, permis de séjour et santé en Italie.","published":true,"steps":[{"id":"it-universitaly","phase":"before","title":"Pré-inscription sur Universitaly","body":"Les étudiants hors Union européenne font leur pré-inscription sur le portail Universitaly, qui sert aussi à la demande de visa. Les Européens s’inscrivent directement auprès de l’université.","url":"https://www.universitaly.it","urlLabel":"Universitaly","titleEn":"Pre-enrol on Universitaly","bodyEn":"Students from outside the European Union pre-enrol on the Universitaly portal, which is also used for the visa application. Europeans enrol directly with the university.","urlLabelEn":"Universitaly"},{"id":"it-visa","phase":"before","title":"Visa d’études (hors Union européenne)","body":"Nationalité française ou européenne : pas de visa.\nAutres nationalités : visa pour études auprès du consulat d’Italie (admission, ressources, logement, assurance santé).","titleEn":"Student visa (outside the European Union)","bodyEn":"French or European nationality: no visa.\nOther nationalities: student visa from the Italian consulate (admission, funds, accommodation, health insurance)."},{"id":"it-diplome","phase":"before","title":"Faire reconnaître son diplôme","body":"Selon l’université, une « dichiarazione di valore » ou une attestation CIMEA de votre bac peut être demandée. Renseignez-vous tôt : les délais peuvent être longs.","url":"https://www.cimea.it","urlLabel":"CIMEA","titleEn":"Get your diploma recognised","bodyEn":"Depending on the university, a « dichiarazione di valore » or a CIMEA statement of your baccalauréat may be required. Ask early: it can take a long time.","urlLabelEn":"CIMEA"},{"id":"it-codice","phase":"before","title":"Codice fiscale","body":"Le code fiscal italien est demandé partout (logement, banque, téléphone, université). Obtenez-le au consulat avant le départ ou à l’Agenzia delle Entrate à l’arrivée.","url":"https://www.agenziaentrate.gov.it","urlLabel":"Agenzia delle Entrate","titleEn":"Codice fiscale","bodyEn":"The Italian tax code is asked for everywhere (housing, bank, phone, university). Get it at the consulate before leaving or at the Agenzia delle Entrate when you arrive.","urlLabelEn":"Agenzia delle Entrate"},{"id":"it-permesso","phase":"arrival","title":"Permis de séjour (hors Union européenne)","body":"Dans les 8 jours ouvrables après l’arrivée, demandez le « permesso di soggiorno » pour études avec le kit disponible dans les bureaux de poste, puis rendez-vous à la Questura.\nÉtudiants européens restant plus de 3 mois : inscription à l’état civil de la commune (anagrafe).","url":"https://www.portaleimmigrazione.it","urlLabel":"Portale Immigrazione","titleEn":"Residence permit (outside the European Union)","bodyEn":"Within 8 working days of arriving, apply for the student « permesso di soggiorno » with the kit available at post offices, then go to the Questura.\nEuropean students staying more than 3 months: register with the town’s registry office (anagrafe).","urlLabelEn":"Portale Immigrazione"},{"id":"it-sante","phase":"arrival","title":"Santé","body":"Étudiants européens : la Carte européenne d’assurance maladie (TEAM en Italie) couvre les soins.\nAutres nationalités : inscription volontaire au service de santé national (SSN) contre une cotisation annuelle, ou assurance privée.","titleEn":"Health","bodyEn":"European students: the European Health Insurance Card (TEAM in Italy) covers care.\nOther nationalities: voluntary registration with the national health service (SSN) for a yearly fee, or private insurance."},{"id":"it-banque","phase":"arrival","title":"Compte bancaire et carte SIM","body":"Avec le codice fiscale et une pièce d’identité, ouvrez un compte et prenez une carte SIM italienne.","titleEn":"Bank account and SIM card","bodyEn":"With your codice fiscale and an ID, open an account and get an Italian SIM card."},{"id":"it-bourses","phase":"months","title":"Bourses et réductions (DSU, ISEE)","body":"Les organismes régionaux pour le droit aux études (DSU) proposent bourses, logements et repas à prix réduit. Pour les frais d’inscription selon les revenus, l’université demande souvent un ISEE (pour les étrangers : « ISEE parificato »).","titleEn":"Grants and discounts (DSU, ISEE)","bodyEn":"The regional right-to-study bodies (DSU) offer grants, housing and discounted meals. For income-based tuition fees, the university often asks for an ISEE (for foreigners: « ISEE parificato »)."},{"id":"it-travail","phase":"year","title":"Travailler pendant les études","body":"Les étudiants européens peuvent travailler librement. Avec un permis de séjour pour études, le travail à temps partiel est autorisé dans une limite d’heures par semaine fixée par la loi.","titleEn":"Working while studying","bodyEn":"European students can work freely. With a student residence permit, part-time work is allowed within a weekly limit of hours set by law."},{"id":"it-renouvellement","phase":"year","title":"Renouveler son permis de séjour","body":"Hors Union européenne : demandez le renouvellement avant l’expiration, en justifiant de la réussite d’examens selon les règles de votre université.","titleEn":"Renew your residence permit","bodyEn":"Outside the European Union: apply to renew it before it expires, showing that you passed exams according to your university’s rules."}],"titleEn":"Studying in Italy","introEn":"Universitaly pre-enrolment, visa (outside the European Union), codice fiscale, residence permit and health in Italy."}]$en$
where key = 'guides' and md5(value) in ('30c42a19be1f27a57039cdcdfe7ab9d6', 'cf1d05ae76ccd9f239c7e5bc4eb2fa5c');

-- Page « Le LFK » (introduction, anecdotes, frise)
update public.app_settings set value = $en${"facts":[{"id":"fact-fondatrice","text":"Mme Mona Al Khaled, qui fonde le LFK en 1989, est la première femme koweïtienne à avoir obtenu un diplôme universitaire français : une maîtrise de lettres à l'université de Caen. La France l'a décorée de l'ordre du Mérite.","emoji":"🎓","title":"Une fondatrice pionnière","titleEn":"A pioneering founder","textEn":"Mrs Mona Al Khaled, who founded the LFK in 1989, was the first Kuwaiti woman to earn a French university degree: a master’s in literature from the University of Caen. France awarded her the Order of Merit."},{"id":"fact-nationalites","text":"On compte au LFK plus d'une trentaine de nationalités, et le français n'est pas la langue maternelle de beaucoup de ses élèves : l'enseignement y est multilingue et multiculturel.","emoji":"🌍","title":"Plus de trente nationalités","titleEn":"More than thirty nationalities","textEn":"More than thirty nationalities study at the LFK, and French is not the mother tongue of many of its students: teaching is multilingual and multicultural."},{"id":"fact-salmiya","text":"Le lycée a grandi sur Hamad Al-Mubarak Street, à Salmiya, classe après classe, de la toute petite section jusqu'à la Terminale.","emoji":"📍","title":"À Salmiya, au bord du Golfe","titleEn":"In Salmiya, on the Gulf","textEn":"The lycée grew on Hamad Al-Mubarak Street, in Salmiya, class after class, from the youngest nursery section all the way to the Terminale."},{"id":"fact-homologue","text":"Le LFK est homologué par le ministère français de l'Éducation nationale : il suit les programmes français, prépare au baccalauréat et a à sa tête un proviseur titulaire de l'Éducation nationale.","emoji":"🏫","title":"Homologué par la France","titleEn":"Accredited by France","textEn":"The LFK is accredited by the French Ministry of Education: it follows the French curriculum, prepares for the baccalauréat and is led by a principal from the French national education system."}],"intro":"Le LFK, une histoire\n\nUne école née d'une conviction\nTout commence en 1989, à Koweït. Le Lycée Français de Koweït est fondé par Mme Mona Al Khaled, première femme koweïtienne à obtenir un diplôme universitaire français (une maîtrise de lettres à l'université de Caen), décorée de l'ordre du Mérite par la France. Son idée tient en peu de mots : offrir aux enfants du pays, comme à ceux des familles venues d'ailleurs, une école qui parle français, mais qui regarde le monde.\nCette ambition n'a pas varié. Dans une petite ville au bord du Golfe, à Salmiya, sur Hamad Al-Mubarak Street, un établissement a grandi, classe après classe, de la toute petite section jusqu'à la Terminale.\n\nUn établissement reconnu\n\nAu fil des années, le LFK s'est ancré dans le réseau de l'enseignement français à l'étranger. Une première convention est signée avec l'AEFE en avril 2002. Le 29 mars 2010, un accord de partenariat la remplace et entre en vigueur le 1er septembre de la même année. Homologué par le ministère français de l'Éducation nationale, le lycée suit les programmes français et prépare au baccalauréat, avec à sa tête un proviseur titulaire de l'Éducation nationale. Il fait aujourd'hui partie du réseau mondial des lycées français à l'étranger.\n\nUne école ouverte sur le monde\nLe LFK ne s'est jamais pensé comme un morceau de France transplanté, mais comme un lieu de rencontre. On y compte plus d'une trentaine de nationalités, et le français n'est pas la langue maternelle de beaucoup de ses élèves. L'enseignement y est multilingue et multiculturel.","timeline":[{"id":"evt-1989","text":"Mme Mona Al Khaled fonde le lycée à Koweït, avec une idée simple : offrir aux enfants du pays, comme à ceux des familles venues d'ailleurs, une école qui parle français, mais qui regarde le monde.","year":"1989","title":"Fondation du Lycée Français de Koweït","titleEn":"The Lycée Français de Koweït is founded","textEn":"Mrs Mona Al Khaled founds the lycée in Kuwait with a simple idea: to offer the country’s children, as well as those of families from elsewhere, a school that speaks French but looks out at the world."},{"id":"evt-2002","text":"En avril 2002, le LFK signe une première convention avec l'AEFE et s'ancre dans le réseau de l'enseignement français à l'étranger.","year":"2002","title":"Première convention avec l'AEFE","titleEn":"First agreement with the AEFE","textEn":"In April 2002, the LFK signs a first agreement with the AEFE and takes root in the network of French schools abroad."},{"id":"evt-2010","text":"Signé le 29 mars 2010, un accord de partenariat remplace la première convention ; il entre en vigueur le 1er septembre 2010.","year":"2010","title":"Accord de partenariat avec l'AEFE","titleEn":"Partnership agreement with the AEFE","textEn":"Signed on 29 March 2010, a partnership agreement replaces the first one; it comes into force on 1 September 2010."},{"id":"evt-aujourdhui","text":"Homologué par l'Éducation nationale, le LFK prépare au baccalauréat et fait partie du réseau mondial des lycées français à l'étranger.","year":"Aujourd'hui","title":"Dans le réseau mondial des lycées français","titleEn":"In the worldwide network of French lycées","textEn":"Accredited by the French Ministry of Education, the LFK prepares for the baccalauréat and is part of the worldwide network of French lycées abroad."}],"introEn":"The LFK, a story\n\nA school born of a conviction\nIt all begins in 1989, in Kuwait. The Lycée Français de Koweït is founded by Mrs Mona Al Khaled, the first Kuwaiti woman to earn a French university degree (a master’s in literature from the University of Caen), whom France awarded the Order of Merit. Her idea fits in a few words: to offer the country’s children, as well as those of families from elsewhere, a school that speaks French but looks out at the world.\nThat ambition has never changed. In a small town on the Gulf, in Salmiya, on Hamad Al-Mubarak Street, a school grew class after class, from the youngest nursery section all the way to the Terminale.\n\nA recognised school\n\nOver the years, the LFK took root in the network of French schools abroad. A first agreement was signed with the AEFE in April 2002. On 29 March 2010, a partnership agreement replaced it and came into force on 1 September of the same year. Accredited by the French Ministry of Education, the lycée follows the French curriculum and prepares for the baccalauréat, led by a principal from the French national education system. Today it is part of the worldwide network of French lycées abroad.\n\nA school open to the world\nThe LFK has never seen itself as a piece of France transplanted, but as a meeting place. More than thirty nationalities study there, and French is not the mother tongue of many of its students. Teaching there is multilingual and multicultural."}$en$
where key = 'lfkStory' and md5(value) = 'c3318dbfc146f11813c43da920226983';

-- Frise des proviseurs et directeurs
update public.app_settings set value = $en$[{"id":"p-gautier","from":2024,"kind":"proviseur","name":"Olivier GAUTIER","photo":"https://www.lfkoweit.edu.kw/wp-content/uploads/2024/09/O.Gautier-e1736772156383.jpg","description":"Consolidateur de l’ALFK","photoFrame":{"x":0,"y":0.17857164655412947,"zoom":1},"descriptionEn":"Consolidator of the ALFK"},{"id":"p-attias","to":2024,"from":2019,"kind":"proviseur","name":"Martial ATTIAS","description":"Initiateur de l’ALFK","photo":"https://xirmnclncldwlnyufaxt.supabase.co/storage/v1/object/public/media/728542b6-2f55-40dd-a389-ab7d443414be/leaders/17e36e01-6bde-41ac-ace4-78f52c0270a2.jpg","descriptionEn":"Initiator of the ALFK"},{"id":"p-lahourcade","to":2019,"from":2001,"kind":"proviseur","name":"Gérard LAHOURCADE"},{"id":"d-fontaine","from":2024,"kind":"directeur","name":"Frédéric FONTAINE","photo":"https://www.lfkoweit.edu.kw/wp-content/uploads/2024/09/F.Fontaine.jpg","photoFrame":{"x":0,"y":0.25027746947835733,"zoom":1}},{"id":"d-bouasker","to":2022,"from":2019,"kind":"directeur","name":"Lounes BOUASKER","photo":"https://xirmnclncldwlnyufaxt.supabase.co/storage/v1/object/public/media/728542b6-2f55-40dd-a389-ab7d443414be/leaders/de4c052a-bdc5-4b10-8c04-739ac291d4d7.jpg"},{"id":"d-jarry","to":2019,"from":2010,"kind":"directeur","name":"Bruno JARRY"},{"id":"c-chelala","kind":"cpe","name":"Pascale CHELALA","photo":"https://www.lfkoweit.edu.kw/wp-content/uploads/2022/10/CHELALA-Pascale.jpg","photoFrame":{"x":0,"y":0.2193018383109806,"zoom":1}}]$en$
where key = 'schoolLeaders' and md5(value) = '20abb82b93a0b477a9c59dea5b67b1ec';

